def get_positive_integer():
    """Reads a positive integer from the user and returns it."""
    while True:
        try:
            num = int(input("Enter a positive integer: "))
            if num > 0:
                return num
            else:
                print("Please enter a positive integer.")
        except ValueError:
            print("That's not a valid integer. Please try again.")

def factorial(n):
    """Calculates the factorial of a given integer n."""
    if n == 0:
        return 1
    else:
        return n * factorial(n-1)

positive_integer = get_positive_integer()
factorial_value = factorial(positive_integer)
print(f"{positive_integer}! = {factorial_value}")
```
When you run this program, it will prompt the user to enter a positive integer. Once a valid positive integer is entered, the program calculates its factorial using a recursive function and prints the result.
